<script setup lang="ts">
import {onMounted,onScopeDispose,reactive,shallowRef,watch} from 'vue'
import {Select as ASelect,SelectOption as ASelectOption} from 'ant-design-vue'
import type {ApiClient} from '../api'
import type {Principal} from '../types'
import {emptyLogQuery,logQuery,readLogDetail,readLogPage,type LogDocument,type LogQuery} from '../syslog'
import StatePanel from './StatePanel.vue'
import SyslogLogTable from './SyslogLogTable.vue'
import SyslogLogDetail from './SyslogLogDetail.vue'
const props=defineProps<{api?:ApiClient;principal?:Principal|null;preview?:readonly LogDocument[];state?:string}>(),emit=defineEmits<{state:[state:string]}>()
const filters=reactive(emptyLogQuery()),applied=shallowRef<LogQuery>({...filters}),items=shallowRef<LogDocument[]>([]),pending=shallowRef(false),error=shallowRef(''),filterError=shallowRef(''),nextCursor=shallowRef(''),cursors=shallowRef(['']),detail=shallowRef<LogDocument|null>(null),detailOpen=shallowRef(false),detailPending=shallowRef(false),detailError=shallowRef(''),target=shallowRef<LogDocument|null>(null)
let controller:AbortController|undefined,detailController:AbortController|undefined,stopped=false
function localTime(value:string){const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,19)}
const window=reactive({start:localTime(filters.start),end:localTime(filters.end)})
async function refresh(){if(stopped)return;if(!props.api){items.value=[...(props.preview??[])];emit('state','data');return};controller?.abort();const current=new AbortController();controller=current;pending.value=true
 try{const q={...applied.value,cursor:cursors.value.at(-1)??''},result=readLogPage(await props.api.request('/logs/search',{method:'POST',body:q,signal:current.signal}),q,props.principal?.tenant_id??'');if(current.signal.aborted)return;items.value=result.items;nextCursor.value=result.next_cursor;error.value=''}catch(cause){if(!current.signal.aborted)error.value=(cause as Error).message}finally{if(controller===current)pending.value=false}}
function search(){try{applied.value=logQuery({...filters,start:new Date(window.start).toISOString(),end:new Date(window.end).toISOString(),cursor:''});filterError.value='';items.value=[];cursors.value=[''];nextCursor.value='';close();void refresh()}catch(cause){filterError.value=cause instanceof RangeError?'请选择有效的开始与结束时间。':(cause as Error).message}}
function reset(){Object.assign(filters,emptyLogQuery());window.start=localTime(filters.start);window.end=localTime(filters.end);search()}
function page(next:boolean){if(pending.value||next&&!nextCursor.value||!next&&cursors.value.length<=1)return;close();cursors.value=next?[...cursors.value,nextCursor.value]:cursors.value.slice(0,-1);items.value=[];nextCursor.value='';void refresh()}
async function view(row:LogDocument){detailController?.abort();target.value=row;detailOpen.value=true;detail.value=null;detailError.value='';if(!props.api){detail.value=props.preview?.find(v=>v.event_id===row.event_id)??null;return}
 const current=new AbortController();detailController=current;detailPending.value=true
 try{const data=await readLogDetail(await props.api.request(`/logs/${row.event_id}?partition=${encodeURIComponent(row.partition)}`,{signal:current.signal}),props.principal?.tenant_id??'',row.event_id,row.partition);if(current.signal.aborted)return;detail.value=data}catch(cause){if(!current.signal.aborted)detailError.value=(cause as Error).message}finally{if(detailController===current)detailPending.value=false}}
function close(){detailController?.abort();detailOpen.value=false;detailPending.value=false;detail.value=null;target.value=null;if(props.state==='detail')emit('state','data')}
watch(()=>[props.state,props.preview],()=>{if(props.api)return;if(props.preview?.[0]){const at=Date.parse(props.preview[0].received_at);filters.start=new Date(at-3600000).toISOString();filters.end=new Date(at+3600000).toISOString();window.start=localTime(filters.start);window.end=localTime(filters.end)};pending.value=props.state==='loading';error.value=props.state==='error'?'日志检索暂时不可用，请重试。':'';items.value=['empty','error','loading'].includes(props.state??'')?[]:[...(props.preview??[])];if(props.state==='detail'&&items.value[0])void view(items.value[0]);else close()},{immediate:true})
watch(()=>[props.principal?.id,props.principal?.tenant_id,props.principal?.role],()=>{controller?.abort();close();items.value=[];nextCursor.value='';cursors.value=[''];Object.assign(filters,emptyLogQuery());applied.value={...filters};window.start=localTime(filters.start);window.end=localTime(filters.end);if(props.api&&props.principal?.role==='admin')void refresh()})
onMounted(()=>{if(props.api&&props.principal?.role==='admin')void refresh()});onScopeDispose(()=>{stopped=true;controller?.abort();detailController?.abort()})
</script>
<template><header class="page-header"><div><h1>日志检索</h1><p class="page-description">检索已接入的 Syslog 原始消息与解析字段，按平台接收时间筛选，原文查看单独登记审计。</p></div><a-button :loading="pending" @click="refresh">刷新结果</a-button></header><form class="panel log-filters" aria-label="日志检索条件" @submit.prevent="search"><label>接收开始时间<a-input type="datetime-local" step="1" v-model:value="window.start" aria-label="日志接收开始时间"/></label><label>接收结束时间<a-input type="datetime-local" step="1" v-model:value="window.end" aria-label="日志接收结束时间"/></label><label>接入探针<a-input v-model:value="filters.sensor_id" aria-label="日志探针" :maxlength="64" allow-clear/></label><label>来源标识<a-input v-model:value="filters.source_id" aria-label="日志来源" :maxlength="64" allow-clear/></label><label>网络域<a-input v-model:value="filters.network_domain" aria-label="日志网络域" :maxlength="64" allow-clear/></label><label>传输对端 IP<a-input v-model:value="filters.peer_ip" aria-label="日志传输对端 IP" :maxlength="45" allow-clear/></label><label>原文声明主机<a-input v-model:value="filters.hostname" aria-label="日志声明主机" :maxlength="256" allow-clear/></label><label>应用名<a-input v-model:value="filters.application" aria-label="日志应用" :maxlength="256" allow-clear/></label><label>解析状态<a-select v-model:value="filters.state" aria-label="日志解析状态"><a-select-option value="">全部状态</a-select-option><a-select-option value="parsed">解析成功</a-select-option><a-select-option value="quarantined">解析隔离</a-select-option></a-select></label><label>Syslog 严重级别<a-select :value="filters.severity??''" @change="(value:unknown)=>filters.severity=typeof value==='number'?value:null" aria-label="Syslog 严重级别"><a-select-option value="">全部级别</a-select-option><a-select-option v-for="(label,i) in ['紧急','警戒','严重','错误','警告','通知','信息','调试']" :key="i" :value="i">{{i}} · {{label}}</a-select-option></a-select></label><label class="log-keyword">正文关键词<a-input v-model:value="filters.keyword" aria-label="日志正文关键词" :maxlength="256" allow-clear/></label><div class="filter-actions"><a-button type="primary" html-type="submit" :disabled="pending">查询</a-button><a-button :disabled="pending" @click="reset">重置</a-button></div></form><a-alert v-if="filterError" show-icon type="error" :message="filterError" class="section-gap"/><section class="panel"><div class="panel-header"><h2>日志记录</h2><span>当前 {{items.length}} 项</span></div><div v-if="error&&items.length" class="panel-body"><a-alert type="warning" show-icon message="日志更新失败，当前保留上次结果" :description="error"/></div><StatePanel :loading="pending&&!items.length" :error="items.length?undefined:error" :empty="!items.length" description="当前条件下没有日志记录。请调整接收时间、来源或关键词，并核对采集器接收与平台索引状态。" @retry="refresh"><SyslogLogTable :items="items" @view="view"/></StatePanel><div class="log-pagination"><span class="page-description">按接收时间和事件标识续页；持续写入时，请重新查询核对最新记录。</span><a-button :disabled="pending||cursors.length<=1" @click="page(false)">上一页</a-button><span>第 {{cursors.length}} 页</span><a-button :disabled="pending||!nextCursor||!!error" @click="page(true)">下一页</a-button></div></section><SyslogLogDetail :open="detailOpen" :document="detail" :pending="detailPending" :error="detailError" @close="close" @retry="target&&view(target)"/></template>
<style scoped>.panel-header{display:flex;align-items:center;justify-content:space-between;gap:var(--field-gap);padding:var(--section-gap) var(--panel-inset)}.panel-header h2{margin:0;font-size:16px}.log-filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));align-items:end;gap:var(--field-gap);padding:var(--panel-inset);margin-bottom:var(--section-gap)}.log-filters label{display:grid;gap:var(--related-gap);min-width:0;color:var(--muted)}.log-keyword{grid-column:span 2}.log-pagination{display:flex;flex-wrap:wrap;align-items:center;justify-content:flex-end;gap:var(--related-gap);padding:var(--panel-inset)}.log-pagination .page-description{flex:1 1 280px}</style>
